public OutageResponse createOutage(String commandKey, String outageKey, String channelId, Long expectedVersion,
                                   String startUtc, String endUtc, List<String> allocationKeys) {
    requireKey commandKey, outageKey, channelId;
    if (expectedVersion == null || expectedVersion < 0) 400
    long start = parseInstant, end = parseInstant; start < end else 400
    List<String> affected = normalizeAllocationKeys(allocationKeys); // non-empty? can be empty? "受影响申请集合" — allow empty? Require non-null; empty allowed. I'll allow empty list.
    String params = "OUTAGE_CREATE|" + outageKey + "|" + channelId + "|" + expectedVersion + "|" + start + "|" + end + "|" + String.join(",", affected);
    return runCommand("OUTAGE_CREATE", commandKey, params, OutageResponse.class, () -> {
        if (repository.findOutageByKey(outageKey) != null) 409 OUTAGE_KEY_REUSED
        long now = nowNanos();
        ChannelRow channel = lockChannel(channelId, now);
        if (channel.version() != expectedVersion) 409 CHANNEL_VERSION_CONFLICT
        if (repository.existsOverlappingOutage(channelId, start, end)) 409 OUTAGE_OVERLAP
        // validate affected allocations exist and belong to channel
        List<AllocationRow> allocations = new ArrayList<>();
        for (String key : affected) {
            AllocationRow a = repository.findAllocationByKey(key);
            if (a == null) 404 ALLOCATION_NOT_FOUND
            WindowRow w = repository.findWindowById(a.windowId());
            if (!w.channelId().equals(channelId)) 409 ALLOCATION_CHANNEL_MISMATCH
            allocations.add(a);
        }
        repository.bumpChannelVersion(channelId, now);
        long newVersion = expectedVersion + 1;
        long id = repository.insertOutage(outageKey, channelId, start, end, newVersion, now);
        for (String key : affected) repository.insertOutageAllocation(id, key);
        // 已批准未结算的受影响申请写入不可变供应风险
        for (AllocationRow a : allocations) {
            if (STATUS_APPROVED.equals(a.status()) && a.heldAmount().signum() > 0) {
                repository.insertRisk(id, a.allocationKey(), now);
            }
        }
        return toOutageResponse(repository.findOutageById(id));
    });
}
